// === Tab: mySketch ===
/* Borrowing from Splash! (Deconstructed) https://openprocessing.org/sketch/912112/

  ___  ___   ___  ___ _  _ _ _ _ 
 | _ )/ _ \ / _ \/ __| || | | | |
 | _ \ (_) | (_) \__ \ __ |_|_|_|
 |___/\___/ \___/|___/_||_(_|_|_)

@Cartocopia - 2023-04-27

for the #WCCChallenge "Splatter"

Mouseclick resets with a random hue.

*/

var word = "BOOSH!!!";
var wordSize = 100;
var splitCount = 4;
var minHue;
var maxHue;
var currentHue;
var font;
var particles = [];
var countdown = 8;
var boosh = false;
var starttime;


function preload() {
	font = loadFont("https://openprocessing.org/sketch/1913348/files/Starborn.otf");
}

function setup() {
	createCanvas(1112, 834);
	colorMode(HSB, 255);
	startmeup();
}

function draw() {

	background(0, 128);
	stroke(255);
	noFill();
	strokeWeight(2)
	rect(0.18 * width, 0.18 * height, 0.64 * width, 0.64 * height); //frame

	if (millis()-starttime < countdown * 1000) {  //timer
		stroke(color(currentHue,255,255));
		strokeWeight(2);
		noFill();
		textSize(wordSize);
		textAlign(CENTER);
		textFont(font);
    text(nf(countdown-floor((millis()-starttime)/1000)), 0.5*width, 0.65*height);
	} else { //detonate
		if (boosh == false) {
			boosh = true;
			for (let i = particles.length - 1; i > -1; i--) {
				particles[i].detonate();
			}
		}
	}

	for (let i = particles.length - 1; i > -1; i--) {
		particles[i].move();
		stroke(particles[i].color);
		//strokeWeight(particles[i].size);
		strokeWeight(2);
		point(particles[i].pos.x, particles[i].pos.y);

		if (particles[i].pos.y > height || particles[i].pos.x < 0 || particles[i].pos.x > width) {
			particles.splice(i, 1);
		}
	}
}

function mouseClicked() {
	startmeup();
}

function startmeup() {
	background(0);
	currentHue = floor(random(255));
  minHue = currentHue;
  maxHue = (currentHue+60)%255;

	particles = [];

	//map the word
	let spawnPoints = font.textToPoints(word, 0.5*width, 0.5*height, wordSize, {
		sampleFactor: 0.6
	});
	spawnPoints.sort((pnt1, pnt2) => (pnt1.x > pnt2.x) ? 1 : -1);

	let firstPoint = spawnPoints[0];
	let lastPoint = spawnPoints[spawnPoints.length - 1];
	let wordHalfWidth = (lastPoint.x - firstPoint.x) / 2.0;

	for (let i = 0; i < spawnPoints.length; i++) {
		let x = spawnPoints[i].x - wordHalfWidth;
		let y = spawnPoints[i].y;
		let newParticle = new Particle(x, y, 1);
		newParticle.setTarget(x, y);
		particles.push(newParticle);
	}
	starttime=millis();
	boosh=false;
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

// === Tab: particle ===
//borrowing from https://openprocessing.org/sketch/912112/

function Particle(x, y, pSize) {
	this.size = pSize;
	this.color = color(currentHue, 255, 255);
	this.gravityAmount = random(0.15, 0.25);
	this.pos = new p5.Vector(x, y);
	this.vel = new p5.Vector(0, 0);
	this.acc = new p5.Vector(0, 0);
	this.target = null;

	this.setTarget = function(x, y) {
		this.target = new p5.Vector(x, y);
	}

	this.seekTarget = function() {
		let targetDist = dist(this.pos.x, this.pos.y, this.target.x, this.target.y);
		let speedMultiplier = 1;
		let distThresh = 50;

		if (targetDist < distThresh) {
			speedMultiplier = targetDist / distThresh;
		}

		if (targetDist > 1) {
			let steer = new p5.Vector(this.target.x, this.target.y);
			steer.sub(this.pos);
			steer.normalize();
			steer.mult(0.05 * speedMultiplier);
			this.acc.add(steer);
		}
	}

	this.shiftHue = function() {
		currentHue = (currentHue + 0.2) % 255;
		if (maxHue < 255) {
			if (currentHue > maxHue) {
				currentHue = minHue;
			}
		} else {
			if (currentHue > maxHue - 255) {
				currentHue = minHue;
			}
		}
	}

	this.detonate = function() {
		this.target = null;
		this.size = random(0.25, 3);
		this.shiftHue();
		this.color = color(currentHue, 255, 200);
		this.shiftHue();

		// outwards
		this.vel = p5.Vector.sub(this.pos, createVector(0.5 * width, 0.5 * height));
		this.vel.setMag(0.05 * abs(width / 2 - p5.Vector.dist(this.pos, createVector(0.5 * width, 0.5 * height))));

		for (let i = 0; i < splitCount; i++) { //make more
			var newParticle = new Particle(this.pos.x, this.pos.y, random(0.25, 5));

			newParticle.vel.set(this.vel.x, this.vel.y);
			newParticle.vel.mult(random(0.9, 1.1));
			newParticle.vel.rotate(radians(random(-15, 15)));

			if (i < splitCount - 1) {
				newParticle.color = color(currentHue, 255, random(64, 255));
				this.shiftHue();
			}

			particles.push(newParticle);
		}
	}

	this.move = function() {
		this.vel.mult(0.99);

		if (this.target != null) {
			this.seekTarget();

		} else {
			this.acc.add(new p5.Vector(0, this.gravityAmount));
		}

		this.vel.add(this.acc);
		this.pos.add(this.vel);
		this.acc.mult(0);

		if ((this.pos.y < height * 0.2) || (this.pos.y > height * 0.8) || (this.pos.x > width * 0.8) || (this.pos.x < width * 0.2)) {
			this.vel = new p5.Vector(0, 0);
			this.acc = new p5.Vector(0, 0);
		}
	}
}

